let db;
const defaultSettings={showArrows:false};
function load(){try{const d=JSON.parse(localStorage.getItem('bp-demo-v4'));if(d&&Array.isArray(d.prompts)&&Array.isArray(d.constructors)){db=d;db.favorites=db.favorites||[];db.presets=db.presets||[];db.templates=Array.isArray(db.templates)?db.templates:[];return}}catch(e){}db={prompts:clone(factory.prompts),constructors:clone(factory.constructors),presets:[],favorites:[],templates:[],settings:clone(defaultSettings),recents:[]};}
function persist(){try{localStorage.setItem('bp-demo-v4',JSON.stringify(db))}catch(e){toast('Armazenamento indisponível neste visualizador. Exporte seus dados se necessário.')}}
load();
const state={screen:'home',tab:'home',filter:'Tudo',search:'',modal:null,selected:null,answers:{},draft:null,editFrom:null,undo:[],redo:[],expanded:new Set(),editorBlock:null,editorStep:null,unsaved:false,editPrompt:null,showEdited:false,entry:'',promptTextEdit:'',promptTitleEdit:'',toastTimer:null};

// Miniaturas locais: o JSON guarda apenas uma referência. Os bytes ficam no IndexedDB.
const THUMB_DB='bibliopromptos-thumbnails-v1',THUMB_STORE='images';
const thumbUrls=new Map(),thumbAlphaCache=new Map();let thumbDbPromise=null,thumbCrop=null,thumbTarget='prompt';
function openThumbDB(){
 if(!('indexedDB' in window))return Promise.reject(Error('IndexedDB não disponível'));
 if(!thumbDbPromise)thumbDbPromise=new Promise((resolve,reject)=>{
  const req=indexedDB.open(THUMB_DB,1);
  req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains(THUMB_STORE))req.result.createObjectStore(THUMB_STORE)};
  req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||Error('Falha no IndexedDB'));
  req.onblocked=()=>reject(Error('Feche outras abas deste site e tente novamente'));
 }).catch(e=>{thumbDbPromise=null;throw e});
 return thumbDbPromise;
}
async function thumbGet(id){const db=await openThumbDB();return new Promise((res,rej)=>{const req=db.transaction(THUMB_STORE,'readonly').objectStore(THUMB_STORE).get(id);req.onsuccess=()=>res(req.result||null);req.onerror=()=>rej(req.error)});}
async function thumbPut(id,blob){const db=await openThumbDB();return new Promise((res,rej)=>{const req=db.transaction(THUMB_STORE,'readwrite').objectStore(THUMB_STORE).put(blob,id);req.onsuccess=()=>res();req.onerror=()=>rej(req.error)});}
async function thumbDel(id){const db=await openThumbDB();return new Promise((res,rej)=>{const req=db.transaction(THUMB_STORE,'readwrite').objectStore(THUMB_STORE).delete(id);req.onsuccess=()=>res();req.onerror=()=>rej(req.error)});}
async function thumbKeys(){const db=await openThumbDB();return new Promise((res,rej)=>{const req=db.transaction(THUMB_STORE,'readonly').objectStore(THUMB_STORE).getAllKeys();req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error)});}
function allThumbRefs(){const ids=[...db.prompts,...db.constructors,...db.templates,state.draft,state.screen==='prompt-editor'?{thumbnailId:state.promptThumbDraftId}:null].filter(Boolean).map(x=>x.thumbnailId).filter(Boolean);return new Set(ids)}
async function cleanupThumbnails(){try{const keep=allThumbRefs(),keys=await thumbKeys();for(const id of keys)if(!keep.has(id)){await thumbDel(id);if(thumbUrls.has(id)){URL.revokeObjectURL(thumbUrls.get(id));thumbUrls.delete(id)}thumbAlphaCache.delete(id)}}catch(e){console.warn('Limpeza de miniaturas pendente:',e)}}
async function duplicateThumbnail(id){const blob=await thumbGet(id);if(!blob)throw Error('Miniatura ausente');const newId='thumb-'+uid();await thumbPut(newId,blob);return newId}
function thumbMarkup(o,large=false){const id=o?.thumbnailId;return `<span class="symbol media-thumb ${large?'media-thumb-large':''}" ${id?`data-thumb-id="${esc(id)}"`:''} aria-label="${id?'Miniatura personalizada':'Sem miniatura'}">${ico('photo','lg')}</span>`}
function thumbControls(target,o){const has=!!o?.thumbnailId;const help=(target==='constructor'||target==='draft')?'Use uma imagem que represente os resultados possíveis. Você pode escolher qualquer foto.':'Use um exemplo do resultado deste prompt. Você pode escolher qualquer foto.';return `<section class="thumb-controls card"><div class="thumb-controls-head"><strong>Imagem de exemplo</strong></div><div class="thumb-controls-row">${thumbMarkup(o,true)}<div class="thumb-controls-buttons"><button class="secondary" data-act="thumb-add" data-thumb-target="${esc(target)}">${has?'Substituir':'Adicionar'} imagem</button>${has?`<button class="thumb-remove" data-act="thumb-remove" data-thumb-target="${esc(target)}">Remover miniatura</button>`:''}<small>${help}</small></div></div></section>`}
async function hasTransparentPixels(url){
 const img=await loadImage(url),canvas=document.createElement('canvas');
 canvas.width=canvas.height=96;
 const ctx=canvas.getContext('2d',{alpha:true,willReadFrequently:true});if(!ctx)return false;
 ctx.drawImage(img,0,0,96,96);
 const pixels=ctx.getImageData(0,0,96,96).data;
 for(let i=3;i<pixels.length;i+=4)if(pixels[i]<250)return true;
 return false;
}
async function hydrateThumbnails(){const wanted=[...document.querySelectorAll('[data-thumb-id]')];for(const node of wanted){const id=node.dataset.thumbId;try{
 if(!thumbUrls.has(id)){const blob=await thumbGet(id);if(!blob)continue;thumbUrls.set(id,URL.createObjectURL(blob))}
 if(!thumbAlphaCache.has(id)){let alpha=false;try{alpha=await hasTransparentPixels(thumbUrls.get(id))}catch(e){console.warn('Não foi possível verificar transparência:',e)}thumbAlphaCache.set(id,alpha)}
 if(!node.isConnected||node.dataset.thumbId!==id)continue;
 node.classList.toggle('thumb-transparent',thumbAlphaCache.get(id)===true);
 node.innerHTML=`<img src="${thumbUrls.get(id)}" alt="Miniatura personalizada" decoding="async">`;
 }catch(err){console.warn('Miniatura indisponível:',err)}}}
function thumbCurrent(target){if(target==='draft')return state.draft;if(target==='prompt-draft')return {thumbnailId:state.promptThumbDraftId};return item(target,state.selected)}
function pickThumbnail(target){if(!['prompt','constructor','draft','prompt-draft'].includes(target))return;thumbTarget=target;document.getElementById('thumbnailfile')?.click()}
function startThumbnailCrop(file){if(!file.type.startsWith('image/')){toast('Selecione um arquivo de imagem.');return}if(file.size>30*1024*1024){toast('Imagem muito grande (limite de 30 MB).');return}if(thumbCrop)discardThumbnailCrop();const url=URL.createObjectURL(file);thumbCrop={file,url,target:thumbTarget};const current=thumbCurrent(thumbTarget);modal('Enquadrar miniatura','A imagem será recortada em quadrado e otimizada. O original não será guardado.',`<div class="crop-preview-wrap"><img id="thumb-crop-preview" src="${url}" alt="Prévia da miniatura"></div><div class="crop-fields"><label for="thumb-x">Posição horizontal</label><input type="range" id="thumb-x" data-thumb-pos min="0" max="100" value="50"><label for="thumb-y">Posição vertical</label><input type="range" id="thumb-y" data-thumb-pos min="0" max="100" value="50"></div><div class="crop-actions"><button class="secondary" data-act="thumb-cancel">Cancelar</button><button class="primary" data-act="thumb-save">Usar esta miniatura</button></div><p class="small muted">512 × 512 pixels no máximo, WebP em qualidade 86% (ou formato compatível). ${current?.thumbnailId?'A imagem anterior será substituída.':''}</p>`);}
function discardThumbnailCrop(){if(thumbCrop)URL.revokeObjectURL(thumbCrop.url);thumbCrop=null;state.modal=null;renderModal()}
function loadImage(url){return new Promise((res,rej)=>{const img=new Image();img.onload=()=>res(img);img.onerror=()=>rej(Error('Formato não suportado neste navegador'));img.src=url})}
function canvasBlob(canvas,type,quality){return new Promise((res,rej)=>canvas.toBlob(b=>b?res(b):rej(Error('Falha ao codificar imagem')),type,quality))}
async function optimizeThumbnail(file,url,x,y){
 const img=await loadImage(url);const w=img.naturalWidth,h=img.naturalHeight;if(!w||!h||w*h>100000000)throw Error('Dimensões de imagem inválidas ou grandes demais');
 const side=Math.min(w,h),sx=(w-side)*x/100,sy=(h-side)*y/100;let size=Math.min(512,Math.round(side));
 let source=document.createElement('canvas');source.width=Math.min(2048,side);source.height=source.width;
 let c=source.getContext('2d',{alpha:true});if(!c)throw Error('Canvas indisponível');c.imageSmoothingEnabled=true;c.imageSmoothingQuality='high';c.drawImage(img,sx,sy,side,side,0,0,source.width,source.height);
 // Redução progressiva: diminui serrilhados preservando detalhes de alto contraste.
 while(source.width>size*2){const next=document.createElement('canvas');next.width=Math.max(size,Math.ceil(source.width/2));next.height=next.width;const ctx=next.getContext('2d',{alpha:true});ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(source,0,0,next.width,next.height);source=next;}
 if(source.width!==size){const final=document.createElement('canvas');final.width=final.height=size;const f=final.getContext('2d',{alpha:true});f.imageSmoothingEnabled=true;f.imageSmoothingQuality='high';f.drawImage(source,0,0,size,size);source=final;}
 let blob=await canvasBlob(source,'image/webp',.86);
 // Safari antigo pode retornar PNG quando WebP não está disponível.
 if(blob.type!=='image/webp')blob=await canvasBlob(source,'image/png');
 return {blob,width:size,height:size};
}
async function commitThumbnailCrop(){const cur=thumbCrop;if(!cur)return;const btn=document.querySelector('[data-act="thumb-save"]');if(btn){btn.disabled=true;btn.textContent='Otimizando…'}const x=Number(document.getElementById('thumb-x')?.value||50),y=Number(document.getElementById('thumb-y')?.value||50);try{
 const result=await optimizeThumbnail(cur.file,cur.url,x,y);const id='thumb-'+uid();await thumbPut(id,result.blob);
 const target=thumbCurrent(cur.target);if(cur.target==='prompt-draft'){state.promptThumbDraftId=id}else if(target){target.thumbnailId=id;if(cur.target!=='draft')persist();else state.unsaved=true}else throw Error('Item não encontrado');
 discardThumbnailCrop();render();toast(`Miniatura pronta: ${result.width}px · ${Math.round(result.blob.size/1024)} KB`);cleanupThumbnails();
 }catch(e){toast('Não foi possível adicionar: '+e.message);if(btn){btn.disabled=false;btn.textContent='Tentar novamente'}}}
function removeThumbnail(target){const current=thumbCurrent(target);if(!current?.thumbnailId)return;const id=current.thumbnailId;if(target==='prompt-draft')state.promptThumbDraftId=null;else {delete current.thumbnailId;if(target==='draft')state.unsaved=true;else persist()}render();toast('Miniatura removida; ícone de fotografia restaurado.');cleanupThumbnails()}

function go(screen,payload={}){state.screen=screen;state.modal=null;Object.assign(state,payload);if(['home','constructors','settings','recent'].includes(screen))state.tab=screen;window.scrollTo(0,0);render()}
function rec(id,type){db.recents=db.recents.filter(x=>x.id!==id||x.type!==type);db.recents.unshift({id,type,time:Date.now()});db.recents=db.recents.slice(0,20);persist()}
function item(type,id){return (type==='constructor'?db.constructors:db.prompts).find(x=>x.id===id)}
function openItem(type,id){const obj=item(type,id);if(!obj)return toast('Item não encontrado');rec(id,type);if(type==='constructor'){state.selected=id;state.answers={};state.showEdited=false;state.promptTextEdit='';go('use')}else{state.selected=id;go('prompt')}}
function header(title,opts={}){const root=['home','constructors','settings','recent'].includes(state.screen);return `<header class="top"><div class="toprow">${root?`<div class="brand"><strong>BiblioPromptos</strong></div>`:`<button class="back" data-act="back" aria-label="Voltar">${ico('chevron.backward')}</button><div class="top-title">${esc(title)}</div>`}<div class="flex gap8">${opts.action||''}${root?`<button class="new-capsule" data-act="new-menu" aria-label="Criar novo">${ico('plus')}<span>Novo</span></button><button class="icon-btn" data-act="help" aria-label="Ajuda">${ico('questionmark.circle')}</button>`:''}</div></div></header>`}
function tabs(){return `<nav class="tabbar" aria-label="Navegação principal">${[['home','Biblioteca','books.vertical'],['constructors','Construtores','slider.horizontal.3'],['settings','Ajustes','gearshape']].map(([s,t,i])=>`<button class="navitem ${state.tab===s?'active':''}" data-act="go" data-screen="${s}">${ico(i)}<span>${t}</span></button>`).join('')}</nav>`}
function rowItem(o,type,custom={}){return `<button class="row-card" data-act="open" data-type="${type}" data-id="${esc(o.id)}">${thumbMarkup(o)}<span class="row-meta"><strong>${esc(o.title)}</strong><small>${esc(o.description||o.category||'Sem descrição')}</small><span><span class="pill ${type==='constructor'?'kind':''}">${type==='constructor'?'Construtor':'Prompt pronto'}</span> <span class="pill">${esc(o.category||'Geral')}</span></span></span>${ico('chevron.right')}</button>`}
function home(){const all=[...db.constructors.map(x=>({...x,__type:'constructor'})),...db.prompts.map(x=>({...x,__type:'prompt'}))];const matches=all.filter(x=> (state.filter==='Tudo'||(state.filter==='Favoritos'&&db.favorites.includes(x.__type+':'+x.id))||(state.filter==='Prompts'&&x.__type==='prompt')||(state.filter==='Construtores'&&x.__type==='constructor')||state.filter===x.category) && (x.title+' '+x.description+' '+x.category).toLowerCase().includes(state.search.toLowerCase()));return `${header('Biblioteca')}<main class="content home-content"><label class="search">${ico('magnifyingglass')}<input id="search" placeholder="Pesquisar na biblioteca" value="${esc(state.search)}" aria-label="Pesquisar"><span class="hidden">Pesquisar</span></label><div class="chip-frame"><div class="chips">${['Tudo','Favoritos','Prompts','Construtores','Imagem','Texto','Pesquisa','Código'].map(f=>`<button class="chip ${state.filter===f?'active':''}" data-act="filter" data-filter="${f}">${f}</button>`).join('')}</div></div><div class="stack library-results">${matches.length?matches.map(x=>rowItem(x,x.__type)).join(''):'<div class="hint">Nada encontrado para esse filtro.</div>'}</div></main>${tabs()}`}
function constructorList(){return `${header('Construtores')}<main class="content home-content"><div class="section compact"><h2>Seus construtores</h2></div><div class="stack">${db.constructors.map(c=>rowItem(c,'constructor')).join('')}</div><button class="secondary full" style="margin-top:16px" data-act="new-constructor">${ico('plus')} Criar construtor</button></main>${tabs()}`}
function recents(){return `${header('Recentes')}<main class="content"><div class="banner">${ico('clock')}<span>Itens abertos recentemente neste protótipo. Os seus prompts e construtores continuam na Biblioteca.</span></div><div class="stack">${db.recents.length?db.recents.map(x=>{const found=item(x.type,x.id);return found?rowItem(found,x.type):''}).join(''):'<div class="card muted body">Abra um prompt ou construtor e ele aparecerá aqui.</div>'}</div></main>${tabs()}`}
function promptView(){const p=item('prompt',state.selected);if(!p)return home();return `${header('Prompt pronto',{action:`<button class="icon-btn plain" data-act="toggle-favorite" data-type="prompt" aria-label="Favoritar prompt">${ico(db.favorites.includes('prompt:'+state.selected)?'bookmark.fill':'bookmark')}</button><button class="icon-btn plain" data-act="prompt-options" aria-label="Opções do prompt">${ico('ellipsis')}</button>`})}<main class="content"><div class="detail-head"><div class="textwrap"><h1>${esc(p.title)}</h1><p>${esc(p.description||'Texto pronto para copiar')}</p><div class="metric"><span class="pill">Prompt pronto</span><span class="pill">${esc(p.category)}</span></div></div></div>${thumbControls('prompt',p)}<div class="banner">${ico('info.circle')}<span>Este item <b>não faz perguntas</b>. É um texto pronto. Se quiser modificá-lo, abra o menu ••• e salve uma cópia.</span></div><div class="section"><h2>Texto completo</h2><span class="pill">${p.text.length} caracteres</span></div><div class="card body" style="white-space:pre-wrap">${esc(p.text)}</div><div class="btnrow" style="margin-top:13px"><button class="primary" data-act="copy-prompt">${ico('document.on.document')} Copiar texto</button><button class="secondary" data-act="prompt-edit">${ico('pencil')} Editar cópia</button></div></main>`}
function isVisible(b,answers){return !b.visibleIf||String(answers[b.visibleIf.id]??'')===String(b.visibleIf.value)}
function stepDone(step,answers){return step.blocks.filter(b=>isVisible(b,answers)&&b.type!=='fixed').every(b=>String(answers[b.id]??'').trim()!=='')}
function promptFrom(c,answers){let parts=[];for(const s of c.steps){for(const b of s.blocks){if(!isVisible(b,answers))continue;if(b.type==='fixed'){if(b.text.trim())parts.push(b.text.trim());continue}let value=answers[b.id];if(value==null||String(value).trim()==='')continue;if(b.type==='choice'){const op=b.options.find(o=>o.id===value);if(op?.text?.trim())parts.push(op.text.trim())}else if(b.text?.trim()){parts.push(b.text.replace(/\{\{value\}\}/g,String(value).trim()))}}}return parts.join('\n\n')}
function question(b){let r=`<div class="block"><div class="lab">${esc(b.title)} ${b.type==='fixed'?'<span class="pill">Fixo</span>':''}</div>`;if(b.type==='choice'){r+=`<div class="stack" style="gap:7px">${b.options.map(op=>`<button class="choice ${state.answers[b.id]===op.id?'active':''}" data-act="answer" data-q="${esc(b.id)}" data-value="${esc(op.id)}"><span class="circle"></span><span class="choice-text">${esc(op.label)}</span></button>`).join('')}</div>`}else if(b.type==='0.circle'){r+=`<input type="number" inputmode="decimal" data-answer="${esc(b.id)}" placeholder="Ex.: ${esc(b.default||0)}" value="${esc(state.answers[b.id]??'')}">`;if(b.hint)r+=`<p class="inputhint">${esc(b.hint)}</p>`}else if(b.type==='text'){r+=`<textarea data-answer="${esc(b.id)}" placeholder="Digite sua resposta...">${esc(state.answers[b.id]??'')}</textarea>`}else{r+=`<div class="hint">${esc(b.text||'Instrução fixa ainda não preenchida.')}</div>`}return r+'</div>'}
function useConstructor(){const c=item('constructor',state.selected);if(!c)return home();let prevDone=true;let stepsHtml='';c.steps.forEach((s,i)=>{if(!prevDone)return;const visible=s.blocks.filter(b=>isVisible(b,state.answers));stepsHtml+=`<section class="step"><div class="step-h"><span class="step-num">${i+1}</span><strong>${esc(s.title)}</strong>${stepDone(s,state.answers)?ico('checkmark.circle'):''}</div>${visible.map(question).join('')||'<div class="hint">Esta etapa ainda não possui perguntas.</div>'}</section>`;prevDone=stepDone(s,state.answers)});const ready=c.steps.every(s=>stepDone(s,state.answers));const generated=promptFrom(c,state.answers);const presetCount=db.presets.filter(p=>p.constructorId===c.id).length;let output=`<div class="section"><h2>Resultado</h2><span class="pill ${ready?'good':'test'}">${ready?'Completo':'Em construção'}</span></div><div class="card"><div class="preview-label" style="justify-content:flex-end"><button class="textbtn" data-act="copy-generated">${ico('document.on.document','sm')} Copiar</button></div><div class="out" style="margin-top:10px">${esc(generated||'Responda às perguntas acima para construir o prompt.')}</div><div class="btnrow" style="margin-top:12px"><button class="secondary" data-act="edit-generated">${ico('pencil')} Minha edição</button><button class="primary" data-act="save-generated">${ico('square.and.arrow.down')} Salvar prompt</button></div></div>`;return `${header('Usar construtor',{action:`<button class="icon-btn plain" data-act="toggle-favorite" data-type="constructor" aria-label="Favoritar construtor">${ico(db.favorites.includes('constructor:'+state.selected)?'bookmark.fill':'bookmark')}</button><button class="icon-btn plain" data-act="constructor-options" aria-label="Opções do construtor">${ico('ellipsis')}</button>`})}<main class="content"><div class="detail-head"><div class="textwrap"><h1>${esc(c.title)}</h1><p>${esc(c.description)}</p><div class="metric"><span class="pill kind">Construtor</span><span class="pill">${c.steps.length} etapas</span></div></div></div>${thumbControls('constructor',c)}<div class="banner">${ico('slider.horizontal.3')}<span><b>Modo de uso:</b> aqui você apenas responde. A estrutura, a ordem e os blocos ficam protegidos. Para editá-los, existe uma opção discreta no menu •••.</span></div><div class="answer-bar"><h2>Construa seu prompt</h2><button class="textbtn" data-act="show-presets">${ico('bookmark','sm')} Salvas (${presetCount})</button></div>${stepsHtml}${output}<button class="secondary full" style="margin-top:10px" data-act="save-preset">${ico('bookmark')} Salvar estas escolhas</button>${state.showEdited?`<div class="section"><h2>Minha edição</h2></div><div class="card stack"><p class="small muted">A versão automática fica preservada separadamente.</p><textarea id="manual-result" style="min-height:170px">${esc(state.promptTextEdit)}</textarea><div class="btnrow"><button class="secondary" data-act="copy-manual">${ico('document.on.document')} Copiar edição</button><button class="primary" data-act="save-manual">${ico('square.and.arrow.down')} Salvar edição</button></div></div>`:''}<button class="textbtn" style="margin-top:15px" data-act="reset-answers">Recomeçar respostas</button></main>`}
function editStart(source, origin){const c=source?clone(source):{id:'new',title:'Novo construtor',category:'Geral',description:'',steps:[]};state.draft=c;state.editFrom=origin||null;state.undo=[];state.redo=[];state.expanded=new Set(c.steps.map(s=>s.id));state.unsaved=false;state.editorBlock=null;state.editorStep=null;state.entry=origin||'new';go('editor')}
function pushUndo(){state.undo.push(JSON.stringify(state.draft));if(state.undo.length>40)state.undo.shift();state.redo=[];state.unsaved=true;const u=document.querySelector('[data-act="undo"]');if(u)u.disabled=false;const r=document.querySelector('[data-act="redo"]');if(r)r.disabled=true}
function undo(){if(!state.undo.length)return;state.redo.push(JSON.stringify(state.draft));state.draft=JSON.parse(state.undo.pop());render()}
function redo(){if(!state.redo.length)return;state.undo.push(JSON.stringify(state.draft));state.draft=JSON.parse(state.redo.pop());render()}
function modDraft(fn){pushUndo();fn(state.draft);state.modal=null;render()}
function editSteps(){return state.draft.steps.map((s,si)=>`<div class="step-editor sortable-item" data-sorttype="step" data-si="${si}"><div class="namebar"><span class="handle" data-handle="step" data-si="${si}" title="Segurar e arrastar etapa">${ico('list.bullet','lg')}</span><strong>${esc(s.title)}</strong><button class="icon-btn plain" data-act="toggle-step" data-si="${si}" title="Expandir/recolher">${ico(state.expanded.has(s.id)?'chevron.up':'chevron.down')}</button><button class="icon-btn plain" data-act="step-menu" data-si="${si}" title="Opções da etapa">${ico('ellipsis')}</button></div>${state.expanded.has(s.id)?`<div class="step-bod"><div class="lab">Nome da etapa</div><input data-ed="step-title" data-si="${si}" value="${esc(s.title)}" placeholder="Nome da etapa"><p class="inputhint">Blocos desta etapa · arraste os pegadores para reorganizar.</p><div data-sortgroup="blocks" data-si="${si}">${s.blocks.map((b,bi)=>`<div class="editor-item sortable-item" data-sorttype="block" data-si="${si}" data-bi="${bi}"><span class="handle" data-handle="block" data-si="${si}" data-bi="${bi}" title="Segurar e arrastar bloco">${ico('list.bullet')}</span><div class="sub"><strong>${esc(b.title||'(sem título)')}</strong><small>${esc(({choice:'Seleção de opções',number:'Número',text:'Texto livre',fixed:'Instrução fixa'})[b.type])}${b.visibleIf?' · Condicional':''}</small></div>${db.settings.showArrows?`<div class="mini-actions"><button data-act="upblock" data-si="${si}" data-bi="${bi}" title="Subir">${ico('chevron.up')}</button><button data-act="downblock" data-si="${si}" data-bi="${bi}" title="Descer">${ico('chevron.down')}</button></div>`:''}<button class="icon-btn plain" data-act="edit-block" data-si="${si}" data-bi="${bi}" title="Editar bloco">${ico('pencil')}</button><button class="icon-btn plain" data-act="block-menu" data-si="${si}" data-bi="${bi}" title="Outras ações">${ico('ellipsis')}</button></div>`).join('')}</div><button class="addline" data-act="add-block" data-si="${si}">${ico('plus')} Adicionar bloco nesta etapa</button></div>`:''}</div>`).join('')}
function editor(){const d=state.draft;return `${header('Editor Universal',{action:`<button class="icon-btn plain" data-act="editor-help" aria-label="Ajuda do editor">${ico('questionmark.circle')}</button>`})}<main class="content"><div class="banner">${ico('lock')}<span><b>Modo de edição estrutural.</b> Aqui você cria a ferramenta que fará perguntas. Ao salvar uma edição, nasce uma cópia independente; o original permanece intacto.</span></div><div class="editorbar"><div>${ico('pencil.and.list.clipboard')} <b style="font-size:12px">Editor Universal</b><br><small>${state.editFrom?'Editando uma cópia protegida':'Criando estrutura nova'}</small></div><div class="mini-actions"><button data-act="undo" ${!state.undo.length?'disabled':''} title="Desfazer">${ico('arrow.uturn.backward')}</button><button data-act="redo" ${!state.redo.length?'disabled':''} title="Refazer">${ico('arrow.uturn.right')}</button></div></div><div class="card stack"><div><label class="lab">Nome do construtor</label><input data-ed="draft-title" value="${esc(d.title)}" placeholder="Ex.: Restauração de fotografias"></div><div><label class="lab">Descrição</label><input data-ed="draft-description" value="${esc(d.description)}" placeholder="Para que serve este construtor?"></div><div><label class="lab">Categoria</label><select data-ed="draft-category">${['Geral','Imagem','Texto','Código','Pesquisa'].map(t=>`<option ${d.category===t?'selected':''}>${t}</option>`).join('')}</select></div></div>${thumbControls('draft',d)}<div class="section"><h2>Etapas e blocos</h2><span class="pill">${d.steps.length} etapas</span></div><div class="hint" style="margin-bottom:12px">A ordem aqui costuma determinar a ordem dos trechos no prompt final. <b>Segure o pegador</b> ${ico('list.bullet','sm')} para arrastar. A reordenação é liberada somente neste modo de edição.</div><div data-sortgroup="steps">${editSteps()}</div><button class="addline" data-act="add-step">${ico('plus')} Adicionar etapa</button><div class="section"><h2>Verificar e salvar</h2></div><div class="card stack"><button class="secondary full" data-act="preview-draft">${ico('eye')} Testar como usuário</button><button class="primary full" data-act="save-editor">${ico('square.and.arrow.down')} ${state.editFrom?'Salvar como nova cópia':'Salvar novo construtor'}</button><p class="small muted">${state.editFrom?'O construtor original NÃO será sobrescrito. O novo ganhará nome (2), (3)...':'Cria uma nova ferramenta na área Construtores.'}</p></div></main>`}
function settings(){return `${header('Ajustes')}<main class="content home-content"><div class="section compact"><h2>Aparência</h2></div><button class="row-card settings-link" data-act="tokens"><span class="symbol">${ico('slider.horizontal.3','lg')}</span><span class="row-meta"><strong>Design Tokens</strong><small>Cores, textos, dimensões e prévia ao vivo</small></span>${ico('chevron.right')}</button><div class="section compact"><h2>Editor Universal</h2></div><div class="setting-row"><div class="srtext"><strong>Mostrar botões ↑ ↓</strong><small>Alternativa ao arrastar; ocultos por padrão.</small></div><button class="switch toggle ${db.settings.showArrows?'on':''}" role="switch" aria-checked="${db.settings.showArrows}" data-act="toggle-arrows"></button></div><div class="section compact"><h2>Dados e segurança</h2></div><div class="stack" style="gap:8px"><button class="row-card settings-link" data-act="export">${ico('square.and.arrow.up','lg')}<span class="row-meta"><strong>Exportar dados</strong><small>ZIP com prompts, construtores, temas e miniaturas</small></span>${ico('chevron.right')}</button><button class="row-card settings-link" data-act="import">${ico('square.and.arrow.down','lg')}<span class="row-meta"><strong>Importar backup</strong><small>Importar ZIP com imagens ou JSON antigo</small></span>${ico('chevron.right')}</button></div><div class="section compact"><h2>Avançado</h2></div><button class="row-card settings-link" data-act="advanced">${ico('gearshape','lg')}<span class="row-meta"><strong>Recuperação avançada</strong><small>Restaurar exemplos de fábrica sem substituir dados pessoais</small></span>${ico('chevron.right')}</button><p class="settings-note">Protótipo experimental. A publicação permite testar a interface no Safari; os dados permanecem locais neste navegador.</p></main>${tabs()}`}
function advanced(){return `${header('Recuperação avançada')}<main class="content"><div class="banner">${ico('lock')}<span>Esta área fica intencionalmente longe da navegação usual. Restauração não modifica itens personalizados.</span></div><div class="card stack"><h3>Conteúdo inicial do aplicativo</h3><p class="body muted">Os exemplos originais estão embutidos neste arquivo HTML. Se você os remover da biblioteca, poderá recuperá-los aqui.</p><button class="secondary full" data-act="restore-factory">${ico('arrow.trianglehead.counterclockwise.rotate.90')} Restaurar itens originais ausentes</button><p class="small muted">Não substitui nem apaga seus construtores ou prompts personalizados.</p></div><div class="card stack" style="margin-top:12px"><h3>Recomeçar demonstração</h3><p class="body muted">Apaga somente alterações locais desta demonstração e volta aos exemplos iniciais. Não altera arquivos externos.</p><button class="dangerbtn full" data-act="reset-demo">Redefinir somente o protótipo</button></div></main>`}
function newPromptEditor(){const editing=state.editPrompt;return `${header(editing?'Editar cópia de prompt':'Novo prompt')}<main class="content"><div class="banner">${ico('lock')}<span>Salvar cria um <b>novo item independente</b> na Biblioteca. O original, quando houver, permanece inalterado.</span></div><div class="card stack"><div><label class="lab">Nome</label><input id="prompt-title" value="${esc(state.promptTitleEdit)}" placeholder="Título do prompt"></div>${thumbControls('prompt-draft',{thumbnailId:state.promptThumbDraftId})}<div><label class="lab">Texto do prompt</label><textarea id="prompt-text" style="min-height:270px" placeholder="Escreva ou cole o texto final...">${esc(state.promptTextEdit)}</textarea></div><button class="primary full" data-act="save-prompt-edit">${ico('square.and.arrow.down')} Salvar como novo prompt</button></div></main>`}
function render(){let html;switch(state.screen){case'home':html=home();break;case'constructors':html=constructorList();break;case'recent':html=recents();break;case'prompt':html=promptView();break;case'use':html=useConstructor();break;case'editor':html=editor();break;case'settings':html=settings();break;case'tokens':html=tokensPage();break;case'advanced':html=advanced();break;case'prompt-editor':html=newPromptEditor();break;default:html=home()}document.getElementById('app').innerHTML=html;renderModal();hydrateThumbnails()}
function modal(title,subtitle,body){state.modal={title,subtitle,body};renderModal()}
function renderModal(){const root=document.getElementById('modal');if(!state.modal){root.innerHTML='';document.body.classList.remove('modal-open');return}document.body.classList.add('modal-open');const {title,subtitle,body}=state.modal;root.innerHTML=`<div class="overlay" data-act="close-modal"><div class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}" data-stop="yes"><div class="sheetbar"></div><div class="sheet-title-row"><h2>${esc(title)}</h2></div>${subtitle?`<p>${esc(subtitle)}</p>`:''}${body}</div></div>`}
function pick(act,label,desc,icon,attrs=''){return `<button class="pick" data-act="${act}" ${attrs}><span class="icon-wrap">${ico(icon,'lg')}</span><span class="pick-text"><strong>${esc(label)}</strong><small>${esc(desc)}</small></span></button>`}
function showNewMenu(){modal('O que deseja criar?','',pick('new-prompt','Novo prompt pronto','Escrever ou colar um texto para copiar','text.document')+pick('new-constructor','Novo construtor','Criar uma ferramenta para gerar vários prompts','slider.horizontal.3'))}
function showNewConstructor(){modal('Novo construtor','Três pontos de partida. Todos abrem o mesmo Editor Universal.',pick('start-zero','Começar do zero','Etapas e blocos vazios','plus')+pick('choose-duplicate','Duplicar existente','Copiar um construtor seu já preenchido','document.on.document')+pick('choose-template','Utilizar modelo pronto','Catálogo de moldes com lacunas para preencher','rectangle.grid.2x2'))}
function chooseDuplicate(){modal('Duplicar construtor','A cópia será independente e totalmente editável.',db.constructors.map(c=>pick('dup-start',c.title,c.description,'slider.horizontal.3',`data-id="${esc(c.id)}"`)).join(''))}
function chooseTemplates(){const own=db.templates.map(t=>pick('template-start',t.title,t.description||'Modelo pessoal','rectangle.grid.2x2','data-id="'+esc(t.id)+'"')).join('');const builtIn=factory.templates.map(t=>pick('template-start',t.title,t.description,'rectangle.grid.2x2','data-id="'+esc(t.id)+'"')).join('');modal('Catálogo de modelos','Escolha um modelo para iniciar um novo construtor.',(own?'<div class="sep-label">Meus modelos</div>'+own:'')+'<div class="sep-label">Modelos prontos</div>'+builtIn)}
async function saveAsTemplate(){const original=item('constructor',state.selected);if(!original)return toast('Construtor não encontrado');const model=clone(original);model.id='model-'+uid();model.title=versionName(model.title,db.templates);delete model.factory;if(model.thumbnailId){try{model.thumbnailId=await duplicateThumbnail(model.thumbnailId)}catch(e){return toast('Falha ao copiar miniatura; modelo não salvo.')}}model.created=Date.now();db.templates.unshift(model);persist();chooseTemplates();toast('Modelo salvo em Meus modelos. Original preservado.')}
function useOptions(){const c=item('constructor',state.selected);modal('Opções do construtor','A edição da estrutura fica protegida em um menu separado.',pick('reset-answers','Recomeçar respostas','Limpar escolhas desta utilização','arrow.trianglehead.counterclockwise.rotate.90')+pick('edit-structure','Editar estrutura','Modo avançado: cria cópia, preserva original','pencil.and.list.clipboard')+pick('duplicate-current','Duplicar construtor','Abrir cópia preenchida no Editor Universal','document.on.document')+pick('save-as-template','Salvar como modelo','Adicionar ao catálogo de modelos pessoais','rectangle.grid.2x2')+pick('delete-current','Remover da biblioteca','Permite recuperação de itens de fábrica','trash'))}
function promptOptions(){modal('Opções do prompt','A edição salva sempre um novo item.',pick('prompt-edit','Editar como cópia','Mantém o texto original preservado','pencil')+pick('duplicate-prompt','Duplicar prompt','Criar cópia independente do texto','document.on.document')+pick('delete-current-prompt','Remover da biblioteca','Recuperação de fábrica disponível em Avançado','trash'))}
function showTour(){modal('Qual é a diferença?','Explore o aplicativo pelos exemplos abaixo.',`<div class="stack">${pick('tour-prompt','1. Abrir um prompt pronto','Texto direto para copiar; sem perguntas','text.document')}${pick('tour-use','2. Usar um construtor','Responder perguntas e gerar um texto','slider.horizontal.3')}${pick('start-zero','3. Abrir o Editor Universal','Criar etapas, perguntas e opções do zero','pencil.and.list.clipboard')}</div><div class="hint" style="margin-top:13px">O Editor Universal <b>não gera prompts por si</b>. Ele cria os construtores que geram prompts.</div>`)}
function editorHelp(){modal('O que é o Editor Universal?','Esta tela é uma oficina para fabricar construtores.',`<div class="stack"><div class="hint"><b>Etapa:</b> conjunto de perguntas relacionadas.<br><b>Bloco:</b> uma pergunta ou instrução fixa.<br><b>Condição:</b> regra que revela um bloco só quando certa resposta for escolhida.<br><b>Texto associado:</b> trecho que entra no prompt final.</div><button class="secondary" data-act="close-modal">Entendi</button></div>`)}
function stepMenu(si){const s=state.draft.steps[si];modal('Etapa: '+s.title,'Ações disponíveis somente no modo de edição.',pick('dup-step','Duplicar esta etapa','Copia perguntas e regras para outra etapa','document.on.document',`data-si="${si}"`)+pick('remove-step','Excluir do rascunho','Pode desfazer até salvar','trash',`data-si="${si}"`)+(db.settings.showArrows?pick('upstep','Mover etapa para cima','Método alternativo','chevron.up',`data-si="${si}"`)+pick('downstep','Mover etapa para baixo','Método alternativo','chevron.down',`data-si="${si}"`):''))}
function blockMenu(si,bi){const b=state.draft.steps[si].blocks[bi];const other=state.draft.steps.map((s,i)=>i===si?'':pick('move-block-to',`Mover para: ${s.title}`,'Move o bloco para outra etapa','chevron.right',`data-si="${si}" data-bi="${bi}" data-target="${i}"`)).join('');modal('Bloco: '+b.title,'Você pode duplicar, mover ou remover este bloco.',pick('dup-block','Duplicar bloco','Cria outro bloco independente','document.on.document',`data-si="${si}" data-bi="${bi}"`)+other+pick('remove-block','Excluir do rascunho','Pode desfazer até salvar','trash',`data-si="${si}" data-bi="${bi}"`))}
function addBlockMenu(si){modal('Adicionar bloco','Qual componente deseja criar nesta etapa?',pick('create-block','Escolha única','Pergunta com respostas alternativas','checkmark.circle',`data-si="${si}" data-kind="choice"`)+pick('create-block','Campo numérico','Ângulo, intensidade, quantidade etc.','0.circle',`data-si="${si}" data-kind="number"`)+pick('create-block','Texto livre','Campo para o usuário escrever','text.document',`data-si="${si}" data-kind="text"`)+pick('create-block','Instrução fixa','Sempre aparece no prompt, sem pergunta','text.document',`data-si="${si}" data-kind="fixed"`))}
function blockEdit(si,bi){state.editorStep=si;state.editorBlock=bi;const b=state.draft.steps[si].blocks[bi];const choices=b.type==='choice'?`<div class="sep-label">Opções e seus trechos</div>${b.options.map((o,oi)=>`<div class="soft" style="margin-bottom:9px"><div class="lab">Opção ${oi+1}</div><input data-field="option-label" data-oi="${oi}" value="${esc(o.label)}" placeholder="Texto da opção"><div class="lab">Trecho acrescentado ao prompt</div><textarea data-field="option-text" data-oi="${oi}" placeholder="Instrução correspondente...">${esc(o.text)}</textarea><button class="textbtn negative" data-act="remove-option" data-oi="${oi}">${ico('trash','sm')} Excluir opção</button></div>`).join('')}<button class="addline" data-act="add-option">${ico('plus')} Adicionar opção</button>`:`<div class="lab">Texto associado ao bloco</div><textarea data-field="block-text" placeholder="${b.type==='fixed'?'Instrução fixa...':'Ex.: Use this value: {{value}}.'}">${esc(b.text||'')}</textarea>${b.type!=='fixed'?'<p class="inputhint">Use <b>{{value}}</b> onde a resposta deverá aparecer no texto final.</p>':''}`;const conds=state.draft.steps.flatMap(s=>s.blocks.filter(x=>x.id!==b.id&&x.type==='choice').map(x=>({id:x.id,title:x.title,options:x.options})));const hasCond=b.visibleIf&&conds.some(x=>x.id===b.visibleIf.id);let condhtml=`<div class="sep-label">Condição de exibição (opcional)</div><select id="cond-block"><option value="">Sempre mostrar</option>${conds.map(x=>`<option value="${esc(x.id)}" ${b.visibleIf?.id===x.id?'selected':''}>Mostrar se: ${esc(x.title)}</option>`).join('')}</select>`;if(hasCond){const source=conds.find(x=>x.id===b.visibleIf.id);condhtml+=`<div class="lab">Quando a resposta for</div><select id="cond-value">${source.options.map(x=>`<option value="${esc(x.id)}" ${b.visibleIf.value===x.id?'selected':''}>${esc(x.label)}</option>`).join('')}</select>`}modal('Editar bloco',`${b.type==='choice'?'Você está configurando uma pergunta e suas respostas.':'Você está configurando um bloco do construtor.'}`,`<div class="lab">Nome / pergunta</div><input data-field="block-title" value="${esc(b.title)}">${choices}${condhtml}<button class="primary full" style="margin-top:15px" data-act="finish-block">${ico('checkmark')} Concluir bloco</button>`)}
function versionName(title,list){const clean=String(title||'Sem título').replace(/\s*\(\d+\)$/,'').trim();if(!list.some(x=>x.title===clean))return clean;let n=2;while(list.some(x=>x.title===`${clean} (${n})`))n++;return `${clean} (${n})`}
async function saveEditor(){const d=clone(state.draft);if(!d.title.trim())return toast('Dê um nome ao construtor');if(!d.steps.length)return toast('Adicione pelo menos uma etapa');d.id=uid();d.title=versionName(d.title,db.constructors);if(d.thumbnailId){try{d.thumbnailId=await duplicateThumbnail(d.thumbnailId)}catch(err){toast('Falha ao copiar miniatura; construtor não salvo.');return}}delete d.factory;db.constructors.unshift(d);persist();state.selected=d.id;state.draft=null;state.unsaved=false;openItem('constructor',d.id);cleanupThumbnails();toast(`Salvo: ${d.title}. Original preservado.`)}
