function fallbackCopy(text){const input=document.createElement('textarea');input.value=text;input.style.position='fixed';input.style.opacity='0';document.body.appendChild(input);input.select();let ok=false;try{ok=document.execCommand('copy')}catch(e){}input.remove();toast(ok?'Texto copiado!':'Copiar indisponível neste visualizador; selecione o texto.')}
function reallyDelete(type,id){if(!confirm('Remover este item da Biblioteca desta demonstração? Os itens de fábrica podem ser restaurados em Configurações > Avançado.'))return;const arr=type==='prompt'?db.prompts:db.constructors;const ix=arr.findIndex(x=>x.id===id);if(ix>=0){arr.splice(ix,1);persist();go(type==='prompt'?'home':'constructors');cleanupThumbnails();toast('Item removido da biblioteca.')}}
async function backup(){await exportBackupZip()}
// Backup ZIP próprio e portátil (ZIP método Store) com JSON e arquivos de imagem.
const enc=new TextEncoder(),dec=new TextDecoder();
let crcTable=null;
function crc32(bytes){if(!crcTable){crcTable=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;crcTable[n]=c>>>0}}let c=0xffffffff;for(const b of bytes)c=crcTable[(c^b)&255]^(c>>>8);return (c^0xffffffff)>>>0}
function u16(out,pos,v){out[pos]=v&255;out[pos+1]=(v>>>8)&255}function u32(out,pos,v){u16(out,pos,v);u16(out,pos+2,v>>>16)}
function read16(bytes,pos){return bytes[pos]|(bytes[pos+1]<<8)}function read32(bytes,pos){return (bytes[pos]|(bytes[pos+1]<<8)|(bytes[pos+2]<<16)|(bytes[pos+3]<<24))>>>0}
function zipStore(entries){const chunks=[],index=[];let offset=0;for(const [name,body] of entries){const nm=enc.encode(name),data=body instanceof Uint8Array?body:enc.encode(body),crc=crc32(data),local=new Uint8Array(30+nm.length);u32(local,0,0x04034b50);u16(local,4,20);u16(local,6,0x0800);u16(local,8,0);u32(local,14,crc);u32(local,18,data.length);u32(local,22,data.length);u16(local,26,nm.length);local.set(nm,30);chunks.push(local,data);const cent=new Uint8Array(46+nm.length);u32(cent,0,0x02014b50);u16(cent,4,20);u16(cent,6,20);u16(cent,8,0x0800);u32(cent,16,crc);u32(cent,20,data.length);u32(cent,24,data.length);u16(cent,28,nm.length);u32(cent,42,offset);cent.set(nm,46);index.push(cent);offset+=local.length+data.length}const centralSize=index.reduce((s,x)=>s+x.length,0);const eocd=new Uint8Array(22);u32(eocd,0,0x06054b50);u16(eocd,8,entries.length);u16(eocd,10,entries.length);u32(eocd,12,centralSize);u32(eocd,16,offset);return new Blob([...chunks,...index,eocd],{type:'application/zip'})}
function unzipStore(bytes){const entries=new Map();let p=0,n=0;while(p+4<=bytes.length&&read32(bytes,p)===0x04034b50){if(++n>2000)throw Error('ZIP contém arquivos demais');const flags=read16(bytes,p+6),method=read16(bytes,p+8),crc=read32(bytes,p+14),sz=read32(bytes,p+18),len=read16(bytes,p+26),extra=read16(bytes,p+28);if(method!==0||flags&8)throw Error('Este ZIP usa uma compactação não suportada; importe o ZIP exportado pelo aplicativo');const name=dec.decode(bytes.subarray(p+30,p+30+len));const start=p+30+len+extra,end=start+sz;if(end>bytes.length||!name||name.includes('..')||name.startsWith('/'))throw Error('ZIP inválido');const data=bytes.slice(start,end);if(crc32(data)!==crc)throw Error('Arquivo ZIP danificado: '+name);entries.set(name,data);p=end;if(entries.size>1000)throw Error('ZIP contém dados demais')}if(!entries.size)throw Error('ZIP sem dados compatíveis');return entries}
