async function exportBackupZip(){try{const thumbIds=new Set([...db.prompts,...db.constructors,...db.templates].map(x=>x.thumbnailId).filter(Boolean));const entries=[];const manifest={format:'bibliopromptos-backup-zip-v2',created:new Date().toISOString(),data:db,theme:themeValues,images:[]};for(const id of thumbIds){const blob=await thumbGet(id);if(!blob)throw Error('Miniatura não encontrada: '+id);const ext=blob.type==='image/webp'?'webp':blob.type==='image/png'?'png':'jpg';const path=`miniaturas/${id}.${ext}`;entries.push([path,new Uint8Array(await blob.arrayBuffer())]);manifest.images.push({id,path,mime:blob.type})}entries.unshift(['dados.json',JSON.stringify(manifest,null,2)]);const zip=zipStore(entries);triggerDownload(zip,'BiblioPromptosAPP_Backup_'+new Date().toISOString().slice(0,10)+'.zip');toast(`Backup ZIP completo: ${manifest.images.length} miniatura(s).`)}catch(e){toast('Falha no backup: '+e.message)}}
async function importBackupZip(file){try{if(file.size>150*1024*1024)throw Error('Backup acima de 150 MB');const entries=unzipStore(new Uint8Array(await file.arrayBuffer()));const data=entries.get('dados.json');if(!data)throw Error('dados.json não encontrado');const manifest=JSON.parse(dec.decode(data));if(manifest.format!=='bibliopromptos-backup-zip-v2'||!Array.isArray(manifest.data?.prompts)||!Array.isArray(manifest.data?.constructors)||!Array.isArray(manifest.images))throw Error('Versão de backup incompatível');const images=manifest.images.map(entry=>{if(typeof entry.id!=='string'||!/^thumb-[\w-]+$/.test(entry.id)||typeof entry.path!=='string'||!entry.path.startsWith('miniaturas/')||!entries.has(entry.path)||!['image/webp','image/png','image/jpeg'].includes(entry.mime))throw Error('Miniatura inválida no backup');return {id:entry.id,blob:new Blob([entries.get(entry.path)],{type:entry.mime})}});const expected=new Set([...manifest.data.prompts,...manifest.data.constructors,...(manifest.data.templates||[])].map(x=>x.thumbnailId).filter(Boolean));for(const id of expected)if(!images.some(x=>x.id===id))throw Error('Miniatura ausente no backup: '+id);
 if(!confirm('Importar backup ZIP? Isso substitui os dados LOCAIS atuais. Recomendamos exportar primeiro um backup.'))return;
 // Salvar imagens antes de mudar a biblioteca; se falhar, os dados atuais permanecem.
 for(const img of images){await thumbPut(img.id,img.blob);if(thumbUrls.has(img.id)){URL.revokeObjectURL(thumbUrls.get(img.id));thumbUrls.delete(img.id)}}
 db=manifest.data;db.settings={...defaultSettings,...db.settings};db.favorites=db.favorites||[];db.presets=db.presets||[];db.recents=db.recents||[];db.templates=Array.isArray(db.templates)?db.templates:[];themeValues=validateTheme(manifest.theme);saveTheme();applyTheme();persist();go('home');await cleanupThumbnails();toast(`Backup importado: ${images.length} miniatura(s).`);
 }catch(e){toast('Falha ao importar ZIP: '+e.message)}}

function safeImport(file){if(file.name.toLowerCase().endsWith('.zip'))return importBackupZip(file);const reader=new FileReader();reader.onload=()=>{try{const content=JSON.parse(reader.result);if(content.format!=='bibliopromptos-demo-v1'||!Array.isArray(content.data?.prompts)||!Array.isArray(content.data?.constructors))throw Error('Formato inválido');if(!confirm('Importar backup desta demonstração? Substitui os dados LOCAIS atuais deste protótipo. Exporte um backup antes, se desejar.'))return;db=content.data;db.settings={...defaultSettings,...db.settings};db.recents=db.recents||[];db.presets=db.presets||[];db.favorites=db.favorites||[];db.templates=Array.isArray(db.templates)?db.templates:[];persist();go('home');cleanupThumbnails();toast('Backup JSON importado (sem miniaturas de imagens).')}catch(e){toast('JSON incompatível com este protótipo.')}};reader.readAsText(file)}
function restoreFactory(){let a=0;for(const [key,items] of [['prompts',factory.prompts],['constructors',factory.constructors]]){for(const x of items){if(!db[key].some(y=>y.id===x.id)){db[key].push(clone(x));a++}}}persist();toast(a?`${a} item(ns) originais recuperados, sem substituir personalizados.`:'Todos os exemplos originais já estão na biblioteca.')}
