function previewRender(){const d=state.previewConstructor;let ready=true;let stepsHtml='';d.steps.forEach((s,i)=>{if(!ready)return;stepsHtml+=`<section class="step"><div class="step-h"><span class="step-num">${i+1}</span><strong>${esc(s.title)}</strong></div>${s.blocks.filter(b=>isVisible(b,state.answers)).map(question).join('')}</section>`;ready=stepDone(s,state.answers)});return `${header('Prévia do construtor')}<main class="content"><div class="banner">${ico('eye')}<span><b>Modo de teste.</b> Você está vendo o construtor como ele apareceria para quem vai utilizá-lo. Nada foi salvo ainda.</span></div><h2>${esc(d.title)}</h2><p class="small muted" style="margin:5px 0 15px">${esc(d.description)}</p>${stepsHtml}<div class="section"><h2>Prompt produzido</h2></div><div class="out">${esc(promptFrom(d,state.answers)||'Preencha as etapas para gerar o texto.')}</div><button class="secondary full" style="margin-top:14px" data-act="return-editor">${ico('chevron.backward')} Voltar à edição</button></main>`}
