function changeField(el){const type=el.dataset.ed;if(type){pushUndo();const d=state.draft;if(type==='draft-title')d.title=el.value;if(type==='draft-description')d.description=el.value;if(type==='draft-category')d.category=el.value;if(type==='step-title')d.steps[Number(el.dataset.si)].title=el.value;return}if(el.dataset.field){const b=state.draft.steps[state.editorStep].blocks[state.editorBlock];pushUndo();if(el.dataset.field==='block-title')b.title=el.value;if(el.dataset.field==='block-text')b.text=el.value;if(el.dataset.field==='option-label')b.options[Number(el.dataset.oi)].label=el.value;if(el.dataset.field==='option-text')b.options[Number(el.dataset.oi)].text=el.value;return}if(el.id==='cond-block'){const b=state.draft.steps[state.editorStep].blocks[state.editorBlock];pushUndo();if(!el.value){delete b.visibleIf}else{const source=state.draft.steps.flatMap(s=>s.blocks).find(x=>x.id===el.value);b.visibleIf={id:el.value,value:source?.options?.[0]?.id||''}}blockEdit(state.editorStep,state.editorBlock);return}if(el.id==='cond-value'){pushUndo();state.draft.steps[state.editorStep].blocks[state.editorBlock].visibleIf.value=el.value;return}}
document.addEventListener('click',handleClick);document.addEventListener('change',e=>{if(e.target.id==='thumbnailfile'&&e.target.files[0]){startThumbnailCrop(e.target.files[0]);e.target.value='';return}if(e.target.id==='importfile'&&e.target.files[0]){safeImport(e.target.files[0]);e.target.value='';return}if(e.target.matches('[data-ed],[data-field],#cond-block,#cond-value'))changeField(e.target);if(e.target.matches('[data-answer]')){state.answers[e.target.dataset.answer]=e.target.value;render()} });document.addEventListener('input',e=>{if(e.target.id==='search'){state.search=e.target.value;const pos=e.target.selectionStart;render();const v=document.getElementById('search');v.focus();v.setSelectionRange(pos,pos)}if(e.target.matches('[data-answer]'))state.answers[e.target.dataset.answer]=e.target.value;if(e.target.id==='manual-result')state.promptTextEdit=e.target.value;if(e.target.matches('[data-thumb-pos]')){const preview=document.getElementById('thumb-crop-preview');if(preview){const x=document.getElementById('thumb-x')?.value||50,y=document.getElementById('thumb-y')?.value||50;preview.style.objectPosition=x+'% '+y+'%'}}});
