let drag=null;
document.addEventListener('pointerdown',e=>{const grip=e.target.closest('[data-handle]');if(!grip||state.screen!=='editor')return;const node=grip.closest('.sortable-item');if(!node)return;const kind=grip.dataset.handle;const si=Number(grip.dataset.si),bi=Number(grip.dataset.bi);const group=node.parentElement;const siblings=[...group.children].filter(x=>x.classList.contains('sortable-item'));const from=siblings.indexOf(node);if(from<0)return;e.preventDefault();const rect=node.getBoundingClientRect();drag={grip,node,kind,si,bi,from,x:e.clientX,y:e.clientY,height:rect.height,group,to:from,pid:e.pointerId};node.classList.add('dragging');try{grip.setPointerCapture(e.pointerId)}catch(_){}},{passive:false});
document.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.pid)return;e.preventDefault();const dy=e.clientY-drag.y;drag.node.style.transform=`translateY(${dy}px) scale(1.015)`;drag.node.style.pointerEvents='none';const items=[...drag.group.children].filter(x=>x.classList.contains('sortable-item'));const other=items.filter(x=>x!==drag.node);let target=items.length-1;for(const it of other){const box=it.getBoundingClientRect();if(e.clientY<box.top+box.height/2){target=items.indexOf(it);break}}drag.to=target;drag.node.style.pointerEvents='';},{passive:false});
document.addEventListener('pointerup',e=>{if(!drag||e.pointerId!==drag.pid)return;const d=drag;drag=null;d.node.classList.remove('dragging');d.node.style.transform='';if(d.to===d.from)return;modDraft(draft=>{const arr=d.kind==='step'?draft.steps:draft.steps[d.si].blocks;moveArr(arr,d.from,d.to)});toast('Ordem alterada no rascunho. Use Desfazer se necessário.')});document.addEventListener('pointercancel',()=>{if(drag){drag.node.classList.remove('dragging');drag.node.style.transform='';drag=null}});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal){if(thumbCrop)discardThumbnailCrop();else{state.modal=null;renderModal()}}if(state.screen==='editor'&&(e.metaKey||e.ctrlKey)&&e.key==='z'){e.preventDefault();e.shiftKey?redo():undo()}});

// Personalização visual: tokens centrais e referências aplicadas diretamente ao CSS.
const THEME_SCHEMA=[
 ['--bg','Fundo da página','Cor','#f5f6f8'],['--surface','Superfície dos cartões','Cor','#ffffff'],['--surface2','Superfície secundária','Cor','#f4f5f8'],['--text','Texto principal','Cor','#222c38'],['--muted','Texto secundário','Cor','#75808e'],['--accent','Cor de destaque','Cor','#526b91'],['--accentLight','Fundo de destaque','Cor','#edf1f8'],['--line','Cor da borda','Cor','rgba(45,57,77,.105)'],
 ['--success','Sucesso','Cor','#34c759'],['--danger','Erro','Cor','#e22400'],['--warning','Aviso','Cor','#ffb501'],['--info','Informação','Cor','#0189fb'],['--add','Inclusão','Cor','#30bcff'],
 ['--font-base','Fonte dos textos','Fonte','14px'],['--font-title','Fonte dos títulos','Fonte','23px'],['--font-small','Fonte auxiliar','Fonte','12px'],
 ['--r','Arredondamento dos cartões','Raio','20px'],['--radius-button','Arredondamento dos botões','Raio','14px'],['--radius-input','Arredondamento dos campos','Raio','13px'],['--radius-sheet','Arredondamento da janela','Raio','26px'],
 ['--button-height','Altura mínima dos botões','Dimensão','44px'],['--field-height','Altura dos campos','Dimensão','44px'],['--header-min-height','Altura do cabeçalho','Dimensão','50px'],['--icon-size','Tamanho de ícones','Dimensão','19px'],['--icon-box','Caixa dos ícones','Dimensão','42px'],['--thumb-list-size','Miniatura na biblioteca','Dimensão','65px'],['--thumb-detail-size','Miniatura detalhada','Dimensão','91px'],['--content-padding','Margem interna da tela','Espaçamento','17px'],['--gap-unit','Espaçamento padrão','Espaçamento','12px'],
 ['--shadow','Sombra dos cartões','Sombra','0 9px 34px rgba(37,51,73,.055)'],['--glass-opacity','Opacidade do vidro','Efeito','0.93'],['--glass-blur','Desfoque do vidro','Efeito','22px'],['--card-max-width','Largura máxima do aplicativo','Dimensão','540px']
];
const THEME_BASE=Object.fromEntries(THEME_SCHEMA.map(([name,, ,value])=>[name,value]));
const THEME_KEY='bp-design-tokens-v2';let themeValues={},themeUndoStack=[],themeRedoStack=[];
try{const saved=JSON.parse(localStorage.getItem(THEME_KEY));themeValues=validateTheme(saved);if(themeValues['--thumb-list-size']==='55px'){themeValues['--thumb-list-size']='65px';localStorage.setItem(THEME_KEY,JSON.stringify(themeValues))}}catch(_){themeValues={}}
function validateTheme(o){const r={};if(o&&typeof o==='object')for(const [key,val]of Object.entries(o)){if(/^--[a-z][a-z0-9-]{1,50}$/.test(key)&&typeof val==='string'&&val.length<=180&&!/[;{}<>]/.test(val))r[key]=val.trim()}return r}
function saveTheme(){try{localStorage.setItem(THEME_KEY,JSON.stringify(themeValues))}catch(_){}}
function applyTheme(){for(const [key,val]of Object.entries({...THEME_BASE,...themeValues})){document.documentElement.style.setProperty(key,val)}const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.content=themeValues['--bg']||THEME_BASE['--bg']}
function themeCheckpoint(){themeUndoStack.push({...themeValues});if(themeUndoStack.length>60)themeUndoStack.shift();themeRedoStack.length=0}
function themeUndo(){if(!themeUndoStack.length)return toast('Nada para desfazer');themeRedoStack.push({...themeValues});themeValues=themeUndoStack.pop();saveTheme();applyTheme();render()}
function themeRedo(){if(!themeRedoStack.length)return toast('Nada para refazer');themeUndoStack.push({...themeValues});themeValues=themeRedoStack.pop();saveTheme();applyTheme();render()}
function themeReset(){if(!confirm('Restaurar todos os tokens originais? Será possível desfazer enquanto a página estiver aberta.'))return;themeCheckpoint();themeValues={};saveTheme();applyTheme();render();toast('Tema original restaurado.')}
function themeResetOne(name){if(!(name in THEME_BASE))return;themeCheckpoint();delete themeValues[name];saveTheme();applyTheme();render()}
function themeDelete(name){if(name in THEME_BASE)return toast('Token essencial: restaure seu valor, mas não o exclua.');if(!(name in themeValues))return;if(!confirm(`Excluir o token ${name}?`))return;themeCheckpoint();delete themeValues[name];saveTheme();applyTheme();render();toast('Token personalizado excluído.')}
function themeAdd(){const name=(document.getElementById('new-token-name')?.value||'').trim().replace(/^--/,'');const value=(document.getElementById('new-token-value')?.value||'').trim();const key='--'+name;if(!/^--[a-z][a-z0-9-]{1,50}$/.test(key))return toast('Use um nome como "meu-espacamento".');if(key in THEME_BASE||key in themeValues)return toast('Este token já existe.');if(!value||value.length>180||/[;{}<>]/.test(value))return toast('Valor inválido.');themeCheckpoint();themeValues[key]=value;saveTheme();applyTheme();render();toast('Token criado. Associe-o a um componente para alterar a interface.')}
function themeExport(){const blob=new Blob([JSON.stringify({format:'bibliopromptos-theme-v1',tokens:themeValues},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='BiblioPromptosAPP_Tema.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
function themeImport(file){const reader=new FileReader();reader.onload=()=>{try{const o=JSON.parse(reader.result);if(o.format!=='bibliopromptos-theme-v1'||!o.tokens||typeof o.tokens!=='object')throw Error('Arquivo de tema incompatível');if(!confirm('Aplicar tema importado? Você poderá desfazer nesta sessão.'))return;themeCheckpoint();themeValues=validateTheme(o.tokens);saveTheme();applyTheme();render();toast('Tema importado.')}catch(e){toast('Falha ao importar: '+e.message)}};reader.readAsText(file)}
function themeCell(name,label,group,base){const value=themeValues[name]??base;const isCustom=!(name in THEME_BASE);const preview=group==='Cor'?`<span class="token-color" style="background:var(${name})"></span>`:group==='Fonte'?`<span class="token-type-preview" style="font-size:var(${name})">Aa</span>`:group==='Raio'?`<span class="token-radius-preview" style="border-radius:var(${name})"></span>`:group==='Sombra'?`<span class="token-shadow-preview" style="box-shadow:var(${name})"></span>`:group==='Dimensão'?`<span class="token-dim-preview" style="height:var(${name});max-height:62px"></span>`:'<span class="token-generic-preview">Aa</span>';return `<article class="token-card"><div class="token-top"><div class="token-preview">${preview}</div><div class="token-name"><strong>${esc(label)}</strong><small>${esc(name)}</small></div>${isCustom?`<button class="token-mini" data-act="theme-delete" data-name="${esc(name)}" aria-label="Excluir ${esc(label)}">${ico('trash')}</button>`:`<button class="token-mini" data-act="theme-reset-one" data-name="${esc(name)}" aria-label="Restaurar ${esc(label)}">${ico('arrow.trianglehead.counterclockwise.rotate.90')}</button>`}</div><input class="token-input" data-token="${esc(name)}" aria-label="Valor de ${esc(label)}" value="${esc(value)}" spellcheck="false"><small class="token-note">${isCustom?'Personalizado · precisa de vínculo CSS para alterar componentes':group}</small></article>`}
function tokensPage(){const groups=['Cor','Fonte','Raio','Dimensão','Espaçamento','Sombra','Efeito','Personalizado'];const all=[...THEME_SCHEMA,...Object.entries(themeValues).filter(([key])=>!(key in THEME_BASE)).map(([key,val])=>[key,key.slice(2).replace(/-/g,' '),'Personalizado',val])];return `${header('Design Tokens')}<main class="content tokens-content"><div class="tokens-intro">Altere os valores e observe a interface mudar imediatamente. Os tokens originais são protegidos; os personalizados podem ser excluídos.</div><div class="token-actions"><button class="secondary" data-act="theme-undo" ${themeUndoStack.length?'':'disabled'}>${ico('arrow.uturn.backward')} Desfazer</button><button class="secondary" data-act="theme-redo" ${themeRedoStack.length?'':'disabled'}>${ico('arrow.uturn.forward')} Refazer</button></div><div class="tokens-live-preview"><strong>Prévia ao vivo</strong><div class="tokens-preview-row"><button class="primary" type="button">${ico('plus')} Novo</button><input placeholder="Campo de texto" aria-label="Campo ilustrativo"><span class="token-sample-card">Cartão</span></div><small>As alterações também afetam as telas do protótipo.</small></div>${groups.map(g=>{const items=all.filter(x=>x[2]===g);return items.length?`<section class="tokens-group"><h2>${g==='Cor'?'Cores':g==='Fonte'?'Tipografia':g==='Raio'?'Arredondamentos':g==='Dimensão'?'Dimensões':g==='Espaçamento'?'Espaçamentos':g==='Sombra'?'Sombras':g==='Efeito'?'Efeitos':'Criados por você'}</h2><div class="token-grid">${items.map(x=>themeCell(...x)).join('')}</div></section>`:''}).join('')}<section class="card token-create"><h2>Criar token</h2><p class="small muted">Tokens novos ficam disponíveis para usar no CSS. Eles não mudam componentes até serem associados a eles.</p><label class="lab" for="new-token-name">Nome</label><input id="new-token-name" placeholder="ex.: meu-espacamento"><label class="lab" for="new-token-value">Valor</label><input id="new-token-value" placeholder="ex.: 16px ou #778899"><button class="secondary full" data-act="theme-add">${ico('plus')} Criar token</button></section><div class="token-actions" style="margin-top:18px"><button class="secondary" data-act="theme-export">Exportar tema</button><button class="secondary" data-act="theme-import">Importar tema</button></div><button class="dangerbtn full" data-act="theme-reset" style="margin-top:14px">Restaurar aparência original</button></main>`}
applyTheme();

render();

let themeBeforeEdit=null;
document.addEventListener('focusin',e=>{if(e.target.matches('[data-token]'))themeBeforeEdit={...themeValues}});
document.addEventListener('input',e=>{const el=e.target;if(!el.matches('[data-token]'))return;const name=el.dataset.token,value=el.value.trim();if(!value||/[;{}<>]/.test(value)||value.length>180)return;themeValues[name]=value;applyTheme();saveTheme();});
document.addEventListener('focusout',e=>{const el=e.target;if(!el.matches('[data-token]'))return;const before=themeBeforeEdit||{};themeBeforeEdit=null;if(JSON.stringify(before)!==JSON.stringify(themeValues)){themeUndoStack.push(before);themeRedoStack.length=0;const buttons=document.querySelectorAll('[data-act="theme-undo"]');buttons.forEach(b=>b.disabled=false)}});
document.addEventListener('change',e=>{if(e.target.id==='themefile'&&e.target.files?.[0]){themeImport(e.target.files[0]);e.target.value=''}});

